"use client";
/* Whale, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Whale(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("whale"); }, []);
  return React.createElement("piix-sprite", { "name": "whale", ...piixAttrs(props) });
}

export default Whale;
